#include "stdafx.h"#include "HcdElementBase.h"struct SOFDT_P{#include "PrivateVars/OFDT.h"};class KOFDT : public KHcdElementBase  , protected SOFDT_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );  virtual void OnFilledProjectSettings();};static KHcdFactory _OFDT("OFDT", KOFDT::Create);IHcdElement *KOFDT::Create(){  return new KOFDT;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KOFDT, 4 )void KOFDT::InitParm(){#include "PrivateVars/OFDT.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KOFDT::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KOFDT::OnFilledProjectSettings(){  time = DT;  OUTR0 = 1;}void KOFDT::StepCalc( SStepCalcParams &params ){  if( RST )  {    OUTR0 = 1;    time = DT;    return;  }  time -= params.dtS;  if( time > 0 )    return;  OUTR0 = 0;  time = 0;}